package com.ragpipeline.kafka;import com.ragpipeline.model.IngestionJob;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.stereotype.Service;@Service @RequiredArgsConstructor public class IngestionProducer{private final KafkaTemplate<String,IngestionJob> kafka;@Value("${kafka.topics.ingestion-requests}")String topic;public void send(IngestionJob j){kafka.send(topic,j.getDocumentId().toString(),j);}}
